    @BeforeEach void fixture() {
        assertEquals("studyroom_java_test",db.one("SELECT current_database() AS name").get("name"));
        TestDatabaseCleanup.clear(db);
        base=LocalDate.now(BookingPolicy.CAMPUS_ZONE).minusDays(1);clock.set(base.atTime(9,0));remote="s19rt-test-"+UUID.randomUUID();
        String hash=new BCryptPasswordEncoder().encode("S02-test-only-password");
        admin=db.insert("INSERT INTO users(username,password_hash,role,campus_id) VALUES('s19rt_admin',?,'admin','S09-admin')",hash);
        admin2=db.insert("INSERT INTO users(username,password_hash,role,campus_id) VALUES('s19rt_admin2',?,'admin','S15-admin2')",hash);
        student=db.insert("INSERT INTO users(username,password_hash,role,campus_id) VALUES('s19rt_student',?,'student','S09-student')",hash);
        staff=db.insert("INSERT INTO users(username,password_hash,role,campus_id) VALUES('s19rt_staff',?,'staff','S09-staff')",hash);
        other=db.insert("INSERT INTO users(username,password_hash,role,campus_id) VALUES('s19rt_other',?,'student','S14-other')",hash);
        db.update("UPDATE users SET real_name='S19模拟管理员甲' WHERE id=?",admin);
        room=db.insert("INSERT INTO rooms(name,seat_rows,seat_cols) VALUES('S14模拟空间',1,2)");opening.initializeDefaults(room);
        seat1=db.insert("INSERT INTO seats(room_id,seat_no,row_no,col_no) VALUES(?,'01',1,1)",room);seat2=db.insert("INSERT INTO seats(room_id,seat_no,row_no,col_no) VALUES(?,'02',1,2)",room);
    }
    @AfterEach void clearRate() { redis.delete("studyroom-java:rate:login:"+remote); }
    void at(int h,int m,int s) { clock.set(base.atTime(h,m,s)); }
    String token(String role) throws Exception {
        var result=http.perform(post("/api/auth/login").with(r->{r.setRemoteAddr(remote);return r;}).contentType("application/json").content(json.writeValueAsString(Map.of("username","s19rt_"+role,"password","S02-test-only-password")))).andExpect(status().isOk()).andReturn();
        return json.readTree(result.getResponse().getContentAsString()).path("data").path("token").asText();
    }
    long reservation(long user,long seat) { return Store.id(bookings.create(user,new Requests.Reservation(seat,base.toString(),"10:00","11:00")),"id"); }
    String code(long seat) { codes.generate(admin,seat,new Requests.SeatCodeChange(0L,"测试实际生成座位码"));return current(seat); }
    String current(long seat) { return Store.text(db.one("SELECT code_value FROM seat_codes WHERE seat_id=?",seat),"code_value"); }
    MockHttpServletRequestBuilder auth(MockHttpServletRequestBuilder req,String token) { return req.header("Authorization","Bearer "+token); }
    MockHttpServletRequestBuilder checkin(long id,String code,String token) throws Exception { return auth(post("/api/reservations/"+id+"/checkin"),token).contentType("application/json").content(json.writeValueAsString(Map.of("seat_code",code))); }
    Map<String,Object> row(long id) { return db.one("SELECT * FROM reservations WHERE id=?",id); }



    String key(){return UUID.randomUUID().toString();}
    LocalDateTime now(){return LocalDateTime.ofInstant(clock.instant(),BookingPolicy.CAMPUS_ZONE).truncatedTo(java.time.temporal.ChronoUnit.MICROS);}
    String offset(LocalDateTime t){return t.atZone(BookingPolicy.CAMPUS_ZONE).toOffsetDateTime().toString();}
    Requests.RestrictionCreate create(long user){return new Requests.RestrictionCreate(user,offset(base.plusDays(2).atTime(18,0)),"PUBLIC-S19-REASON 管理限制公开原因","PRIVATE-S19-VERIFICATION 工程模拟核实依据",true,key());}
    Requests.RestrictionRelease release(long id){return new Requests.RestrictionRelease(version(id),"PUBLIC-S19-RELEASE 本条解除原因","PRIVATE-S19-RELEASE 工程模拟解除依据",true,key());}
    @SuppressWarnings("unchecked")Map<String,Object> record(Map<String,Object> receipt){return (Map<String,Object>)receipt.get("restriction");}
    long restriction(Map<String,Object> receipt){return Store.id(record(receipt),"id");}
    long version(long id){return Store.id(db.one("SELECT version FROM restrictions WHERE id=?",id),"version");}
    String state(long id){return Store.text(restrictionPolicy.detail(id,now(),false),"status");}
    Map<String,Object> qualify(long user){return restrictionWorkflow.eligibility(user);}
    long booking(long user,long seat,String start,String end){return Store.id(bookings.create(user,new Requests.Reservation(seat,base.toString(),start,end)),"id");}
    long future(long user){return Store.id(bookings.create(user,new Requests.Reservation(seat2,base.plusDays(1).toString(),"12:00","13:00")),"id");}
    long legacy(long user,LocalDateTime start,LocalDateTime end){db.update("UPDATE users SET credit_banned_until=? WHERE id=?",java.sql.Timestamp.valueOf(end),user);return db.insert("INSERT INTO restrictions(user_id,source,starts_at,ends_at,reason,creator_id,verification_note,facts_confirmed,created_at) VALUES(?,'legacy',?,?,'S19明确工程模拟余期接管，原原因起点未知',NULL,NULL,false,?)",user,java.sql.Timestamp.valueOf(start),java.sql.Timestamp.valueOf(end),java.sql.Timestamp.valueOf(start));}
    String facts(){var all=new LinkedHashMap<String,Object>();for(String table:List.of("restrictions","restriction_operations","reservations","usage_records","violations","notifications","audit_events","credit_logs","users"))all.put(table,db.list("SELECT to_jsonb(t)::text AS raw FROM "+table+" t ORDER BY to_jsonb(t)::text"));return all.toString();}
    MockHttpServletRequestBuilder body(MockHttpServletRequestBuilder req,Object payload,String token)throws Exception{return auth(req,token).contentType("application/json").content(json.writeValueAsString(payload));}
    String path(long id){return "/api/admin/restrictions/"+id+"/release";}
    // Explicit recovery-backlog construction after real checkin: S20 checkin itself now settles any already-expired rows.
    long[] pendingAndInUse(){clock.set(base.atTime(8,0));long used=booking(student,seat1,"10:00","11:00"),pending=booking(student,seat2,"12:00","13:00");String raw=code(seat1);clock.set(base.atTime(10,1));assertEquals(200,bookings.checkin(student,used,raw).status());long expired=db.insert("INSERT INTO reservations(user_id,seat_id,res_date,start_time,end_time,status) VALUES(?,?,?,CAST('09:00' AS TIME),CAST('09:30' AS TIME),'pending')",student,seat2,java.sql.Date.valueOf(base));clock.set(base.atTime(10,5,0,123456000));return new long[]{expired,used,pending};}
    @Test void manualRestrictionIsAtomicNoShowFirstPendingCancelledAndInUseKeepsOriginalEnd()throws Exception{
        String token=token("admin");long[] r=pendingAndInUse();var request=create(student);var result=http.perform(body(post("/api/admin/restrictions"),request,token)).andExpect(status().isOk()).andExpect(jsonPath("$.data.restriction.status").value("active")).andExpect(jsonPath("$.data.restriction.verification_source").value("admin_self_report")).andExpect(jsonPath("$.data.effects.settled_unused_count").value(1)).andExpect(jsonPath("$.data.effects.continued_checked_in_count").value(1)).andExpect(jsonPath("$.data.effects.cancelled_pending[0].reservation_id").value(r[2])).andExpect(jsonPath("$.data.eligibility.can_book").value(false)).andReturn();long id=json.readTree(result.getResponse().getContentAsString()).path("data").path("restriction").path("id").asLong();assertEquals("unused_ended",row(r[0]).get("status"));assertEquals("no_show",row(r[0]).get("termination_reason"));assertEquals("checked_in",row(r[1]).get("status"));assertNull(db.one("SELECT ended_at FROM usage_records WHERE reservation_id=?",r[1]).get("ended_at"));assertEquals("cancelled",row(r[2]).get("status"));assertEquals("admin_restriction",row(r[2]).get("termination_reason"));assertEquals(request.reason(),row(r[2]).get("termination_note"));assertEquals(1,db.count("SELECT count(*) FROM violations WHERE user_id=?",student));assertEquals(1,db.count("SELECT count(*) FROM notifications WHERE type='restriction_cancelled' AND restriction_id=?",id));assertEquals(1,db.count("SELECT count(*) FROM notifications WHERE type='restriction_started' AND restriction_id=?",id));clock.set(base.atTime(11,0));bookings.tick();assertEquals("completed",row(r[1]).get("status"));assertEquals(base+"T11:00",db.one("SELECT ended_at FROM usage_records WHERE reservation_id=?",r[1]).get("ended_at"));assertEquals(1,db.count("SELECT count(*) FROM violations WHERE user_id=?",student));
    }
    @Test void typedHttpBooking403CommitsLegacyNoShowAndCancellationInsteadOfRollingBack()throws Exception{
        String owner=token("student");long[] rows=pendingAndInUse();long id=legacy(student,now().minusHours(1),now().plusDays(1));long count=db.count("SELECT count(*) FROM reservations");http.perform(body(post("/api/reservations"),new Requests.Reservation(seat2,base.plusDays(1).toString(),"14:00","15:00"),owner)).andExpect(status().isForbidden()).andExpect(jsonPath("$.details.code").value("booking_restricted")).andExpect(jsonPath("$.details.active_restrictions[0].id").value(id));assertEquals(count,db.count("SELECT count(*) FROM reservations"));assertEquals("unused_ended",row(rows[0]).get("status"));assertEquals("cancelled",row(rows[2]).get("status"));assertEquals("checked_in",row(rows[1]).get("status"));assertNotNull(restrictionPolicy.required(id).get("effects_applied_at"));assertEquals(2,version(id));assertEquals(1,db.count("SELECT count(*) FROM violations WHERE type='no_show'"));String before=facts();qualify(student);restrictionWorkflow.settle();assertEquals(before,facts());
    }
    @Test void firstCheckinCannotEscapeAnUnappliedLegacyRestrictionAnd409Commits()throws Exception{
        String owner=token("student");long id=reservation(student,seat1);String raw=code(seat1);clock.set(base.atTime(10,1));long limit=legacy(student,base.atTime(9,30),base.plusDays(1).atTime(9,0));http.perform(body(post("/api/reservations/"+id+"/checkin"),Map.of("seat_code",raw),owner)).andExpect(status().isConflict()).andExpect(jsonPath("$.details.status").value("cancelled")).andExpect(jsonPath("$.details.termination_reason").value("admin_restriction"));assertEquals("cancelled",row(id).get("status"));assertEquals(0,db.count("SELECT count(*) FROM usage_records"));assertEquals(0,db.count("SELECT count(*) FROM violations"));assertNotNull(restrictionPolicy.required(limit).get("effects_applied_at"));
    }
    @Test void v73FirstDetailAtNoShowDeadlineUsesFreshStateExactlyOnce()throws Exception{
        String owner=token("student");long id=reservation(student,seat1);clock.set(base.atTime(10,15));http.perform(auth(get("/api/reservations/"+id),owner)).andExpect(status().isOk()).andExpect(jsonPath("$.data.status").value("unused_ended"));assertEquals(1,db.count("SELECT count(*) FROM violations WHERE reservation_id=?",id));assertEquals(1,db.count("SELECT count(*) FROM notifications WHERE type='violation'"));String before=facts();http.perform(auth(get("/api/reservations/"+id),owner)).andExpect(status().isOk());assertEquals(before,facts());
    }
    @Test void firstDetailAfterUsingEndCompletesUsageOnlyOnce()throws Exception{
        String owner=token("student");long id=reservation(student,seat1);String raw=code(seat1);clock.set(base.atTime(10,1));bookings.checkin(student,id,raw);clock.set(base.atTime(11,0));http.perform(auth(get("/api/reservations/"+id),owner)).andExpect(status().isOk()).andExpect(jsonPath("$.data.status").value("completed"));assertEquals(1,db.count("SELECT count(*) FROM notifications WHERE type='reservation_completed'"));String before=facts();bookings.detail(student,id);assertEquals(before,facts());
    }
    @Test void overlappingRestrictionsStayIndependentAndReleasingLongestDoesNotGrantBooking(){var a=create(student);a=new Requests.RestrictionCreate(student,offset(base.plusDays(1).atTime(18,0)),a.reason(),a.verificationNote(),true,a.operationId());long shorter=restriction(restrictionWorkflow.create(admin,a)),longer=restriction(restrictionWorkflow.create(admin2,create(student)));assertEquals(2,((List<?>)qualify(student).get("active_restrictions")).size());var released=restrictionWorkflow.release(admin,longer,release(longer));assertEquals(false,((Map<?,?>)released.get("eligibility")).get("can_book"));assertEquals(1,((List<?>)((Map<?,?>)released.get("eligibility")).get("active_restrictions")).size());assertEquals("released",state(longer));assertEquals("active",state(shorter));assertEquals(false,qualify(student).get("can_book"));restrictionWorkflow.release(admin2,shorter,release(shorter));assertEquals(true,qualify(student).get("can_book"));}
    @Test void releaseUnappliedLegacySettlesExistingNoShowButDoesNotCancelFuturePending(){clock.set(base.atTime(8,0));long expired=booking(student,seat1,"09:00","09:30"),future=booking(student,seat2,"12:00","13:00");clock.set(base.atTime(10,0));long id=legacy(student,base.atTime(9,30),base.plusDays(1).atTime(10,0));assertNull(restrictionPolicy.required(id).get("effects_applied_at"));var result=restrictionWorkflow.release(admin,id,release(id));assertEquals("unused_ended",row(expired).get("status"));assertEquals("pending",row(future).get("status"));assertNull(restrictionPolicy.required(id).get("effects_applied_at"));assertEquals(0,db.count("SELECT count(*) FROM notifications WHERE type='restriction_started'"));assertEquals(1,db.count("SELECT count(*) FROM notifications WHERE type='restriction_released'"));assertEquals(1,((Number)((Map<?,?>)result.get("effects")).get("settled_unused_count")).intValue());assertEquals(true,qualify(student).get("can_book"));assertEquals(false,bookings.legacyCredit(student).get("legacy_ban_active"));assertNotNull(bookings.legacyCredit(student).get("legacy_banned_until"));}
    @Test void releaseOneLegacyStillEnforcesAnotherActiveRestriction(){long pending=future(student);long old=legacy(student,now().minusMinutes(1),now().plusDays(2));long remaining=db.insert("INSERT INTO restrictions(user_id,source,starts_at,ends_at,reason,creator_id,verification_note,facts_confirmed,created_at) VALUES(?,'manual',?,?,'other manual',?,'private basis',true,?)",student,java.sql.Timestamp.valueOf(now()),java.sql.Timestamp.valueOf(now().plusDays(1)),admin,java.sql.Timestamp.valueOf(now()));var result=restrictionWorkflow.release(admin,old,release(old));assertEquals("released",state(old));assertEquals("cancelled",row(pending).get("status"));assertEquals(1,((List<?>)((Map<?,?>)result.get("effects")).get("cancelled_pending")).size());assertEquals(false,((Map<?,?>)result.get("eligibility")).get("can_book"));assertNotNull(restrictionPolicy.required(remaining).get("effects_applied_at"));}
    @Test void legacyAdminRemainderUsesInternalConvergenceWithoutGivingOrdinaryPermissions()throws Exception{
        long pending=future(other);db.update("UPDATE users SET role='admin' WHERE id=?",other);long id=legacy(other,now().minusMinutes(1),now().plusDays(1));restrictionRunner.run(new org.springframework.boot.DefaultApplicationArguments(new String[0]));assertEquals("cancelled",row(pending).get("status"));var eligibility=qualify(other);assertEquals(false,eligibility.get("can_book"));assertEquals("role",eligibility.get("blocked_by"));assertEquals("legacy",restrictionPolicy.detail(id,now(),false).get("source"));assertNull(restrictionPolicy.required(id).get("creator_id"));assertEquals(restrictionPolicy.required(id).get("ends_at"),db.one("SELECT credit_banned_until FROM users WHERE id=?",other).get("credit_banned_until"));}
    @Test void disabledOrdinaryMayBeRestrictedButAdministratorCannotBeManualTarget(){db.update("UPDATE users SET status='disabled' WHERE id=?",staff);var created=restrictionWorkflow.create(admin,create(staff));assertEquals("disabled",((Map<?,?>)created.get("eligibility")).get("blocked_by"));assertEquals(1,((List<?>)((Map<?,?>)created.get("eligibility")).get("active_restrictions")).size());assertEquals(400,assertThrows(Api.Failure.class,()->restrictionWorkflow.create(admin,create(admin2))).status);}
    @Test void sourceCreditFieldsAndLowScoreNoLongerControlEligibilityAfterLegacyRelease(){db.update("UPDATE users SET credit_score=0,credit_banned_until=? WHERE id=?",java.sql.Timestamp.valueOf(base.plusDays(20).atTime(9,0)),student);assertEquals(true,qualify(student).get("can_book"));long id=legacy(student,now(),base.plusDays(10).atTime(9,0));assertEquals(false,qualify(student).get("can_book"));restrictionWorkflow.release(admin,id,release(id));assertEquals(true,qualify(student).get("can_book"));assertEquals(false,bookings.legacyCredit(student).get("legacy_ban_active"));assertEquals(0,db.count("SELECT credit_score FROM users WHERE id=?",student));assertEquals(0,db.count("SELECT count(*) FROM credit_logs"));}
    @Test void endsAtExactNowIsExpiredAndRelease409CannotPretendSuccess()throws Exception{
        String token=token("admin");var request=create(student);request=new Requests.RestrictionCreate(student,offset(now().plusMinutes(1)),request.reason(),request.verificationNote(),true,request.operationId());long id=restriction(restrictionWorkflow.create(admin,request));var release=release(id);clock.set(LocalDateTime.parse(Store.text(restrictionPolicy.required(id),"ends_at")));String before=facts();http.perform(body(post(path(id)),release,token)).andExpect(status().isConflict()).andExpect(jsonPath("$.details.restriction.status").value("expired"));assertEquals(before,facts());assertEquals(true,qualify(student).get("can_book"));assertEquals(0,db.count("SELECT count(*) FROM notifications WHERE type='restriction_released'"));}
    @Test void durableCreateAndReleaseOperationReplaysDoNotReconcileNewFacts(){var request=create(student);var first=restrictionWorkflow.create(admin,request);long id=restriction(first);var release=release(id);restrictionWorkflow.release(admin,id,release);db.insert("INSERT INTO reservations(user_id,seat_id,res_date,start_time,end_time,status) VALUES(?,?,?,'08:00','09:00','pending')",student,seat1,java.sql.Date.valueOf(base));clock.set(base.atTime(10,0));String before=facts();assertEquals(true,restrictionWorkflow.create(admin,request).get("replayed"));assertEquals(true,restrictionWorkflow.release(admin,id,release).get("replayed"));assertEquals(before,facts());assertEquals(0,db.count("SELECT count(*) FROM violations"));assertEquals(409,assertThrows(Api.Failure.class,()->restrictionWorkflow.create(admin2,request)).status);assertEquals(409,assertThrows(Api.Failure.class,()->restrictionWorkflow.create(admin,new Requests.RestrictionCreate(student,request.endsAt(),"changed",request.verificationNote(),true,request.operationId()))).status);assertEquals(409,assertThrows(Api.Failure.class,()->restrictionWorkflow.release(admin,id,new Requests.RestrictionRelease(release.version(),"changed",release.verificationNote(),true,release.operationId()))).status);}
    @Test void twoConcurrentSameCreateKeysReturnOneRestrictionAndOneStartedNotification()throws Exception{var request=create(student);var barrier=new CyclicBarrier(2);var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->{barrier.await();return restrictionWorkflow.create(admin,request);});var b=pool.submit(()->{barrier.await();return restrictionWorkflow.create(admin,request);});assertEquals(restriction(a.get(20,TimeUnit.SECONDS)),restriction(b.get(20,TimeUnit.SECONDS)));}finally{pool.shutdownNow();}assertEquals(1,db.count("SELECT count(*) FROM restrictions"));assertEquals(1,db.count("SELECT count(*) FROM restriction_operations"));assertEquals(1,db.count("SELECT count(*) FROM notifications WHERE type='restriction_started'"));}
    @Test void sourceReplayEffectsArePersistedButQualificationIsPureCurrent()throws Exception{long pending=future(student);var request=create(student);var first=restrictionWorkflow.create(admin,request);long id=restriction(first);clock.set(base.plusDays(3).atTime(9,0));String before=facts();var replay=restrictionWorkflow.create(admin,request);assertEquals(true,replay.get("replayed"));assertEquals(json.readTree(json.writeValueAsString(first.get("effects"))),json.readTree(json.writeValueAsString(replay.get("effects"))));assertEquals("expired",record(replay).get("status"));assertEquals(true,((Map<?,?>)replay.get("eligibility")).get("can_book"));assertEquals(before,facts());assertEquals("cancelled",row(pending).get("status"));}
    @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(strings={"fact","cancel_notification","start_notification","cancel_audit","apply_audit","operation"})
    void anyCreateDependencyFailureRollsBackRestrictionNoShowCancelUsageNotificationAndAudit(String layer)throws Exception{
        String token=token("admin");pendingAndInUse();String before=facts();String table=switch(layer){case "fact"->"restrictions";case "cancel_notification","start_notification"->"notifications";case "operation"->"restriction_operations";default->"audit_events";};String condition=switch(layer){case "fact"->"source<>'manual'";case "cancel_notification"->"type<>'restriction_cancelled'";case "start_notification"->"type<>'restriction_started'";case "cancel_audit"->"action<>'reservation.restriction_cancel'";case "apply_audit"->"action<>'restriction.apply'";default->"action<>'create'";};db.update("ALTER TABLE "+table+" ADD CONSTRAINT s19_fail CHECK("+condition+") NOT VALID");try{http.perform(body(post("/api/admin/restrictions"),create(student),token)).andExpect(status().isInternalServerError());assertEquals(before,facts());}finally{db.update("ALTER TABLE "+table+" DROP CONSTRAINT s19_fail");}
    }
    @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(strings={"notification","audit","operation"})
    void anyReleaseFailureRollsBackOnlyTheAttemptNotOriginalAppliedHistory(String layer)throws Exception{
        String token=token("admin");long id=restriction(restrictionWorkflow.create(admin,create(student)));var request=release(id);String before=facts();String table=layer.equals("notification")?"notifications":layer.equals("audit")?"audit_events":"restriction_operations",condition=layer.equals("notification")?"type<>'restriction_released'":"action<>'release'";if(layer.equals("audit"))condition="action<>'restriction.release'";db.update("ALTER TABLE "+table+" ADD CONSTRAINT s19_fail CHECK("+condition+") NOT VALID");try{http.perform(body(post(path(id)),request,token)).andExpect(status().isInternalServerError());assertEquals(before,facts());}finally{db.update("ALTER TABLE "+table+" DROP CONSTRAINT s19_fail");}
    }
    @Test void eligibilityAndOwnRecordsDoNotLeakPrivateVerificationOrAnotherUser()throws Exception{
        String owner=token("student"),otherToken=token("other"),adminToken=token("admin");long id=restriction(restrictionWorkflow.create(admin,create(student)));for(String path:List.of("/api/restrictions/mine","/api/booking-eligibility")){String response=http.perform(auth(get(path),owner)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString(java.nio.charset.StandardCharsets.UTF_8);assertFalse(response.contains("PRIVATE-S19-VERIFICATION"));assertFalse(response.contains("verification_note"));assertFalse(response.contains("facts_confirmed"));assertTrue(response.contains("PUBLIC-S19-REASON"));}http.perform(auth(get("/api/restrictions/mine"),otherToken)).andExpect(status().isOk()).andExpect(jsonPath("$.data.items.length()").value(0));http.perform(auth(get("/api/admin/restrictions").param("user_id",Long.toString(student)),adminToken)).andExpect(status().isOk()).andExpect(jsonPath("$.data.items[0].id").value(id)).andExpect(jsonPath("$.data.items[0].verification_note").doesNotExist());http.perform(auth(get("/api/admin/restrictions/"+id),adminToken)).andExpect(status().isOk()).andExpect(jsonPath("$.data.verification_note").value("PRIVATE-S19-VERIFICATION 工程模拟核实依据"));var event=db.one("SELECT * FROM notifications WHERE type='restriction_started' AND restriction_id=?",id);assertEquals(student,Store.id(event,"user_id"));assertFalse(event.toString().contains("PRIVATE-S19"));http.perform(auth(get("/api/availability").param("room_id",Long.toString(room)).param("date",base.plusDays(1).toString()),owner)).andExpect(status().isOk());
    }
    @Test void httpRightsStrictFieldsSelfReportedFactsAndTimePrecisionAreEnforced()throws Exception{
        String owner=token("student"),adminToken=token("admin");http.perform(get("/api/restrictions/mine")).andExpect(status().isUnauthorized());http.perform(body(post("/api/admin/restrictions"),create(student),owner)).andExpect(status().isForbidden());http.perform(auth(get("/api/admin/restrictions"),owner)).andExpect(status().isForbidden());var request=create(student);for(String text:List.of(base+"T10:00",offset(now()),base.plusDays(1)+"T10:00:00.1234567+08:00")){var bad=new Requests.RestrictionCreate(student,text,request.reason(),request.verificationNote(),true,key());http.perform(body(post("/api/admin/restrictions"),bad,adminToken)).andExpect(status().isBadRequest());}var raw=json.convertValue(request,new com.fasterxml.jackson.core.type.TypeReference<LinkedHashMap<String,Object>>(){});for(String extra:List.of("starts_at","source","creator_id","credit_banned_until")){var bad=new LinkedHashMap<>(raw);bad.put(extra,"forged");http.perform(body(post("/api/admin/restrictions"),bad,adminToken)).andExpect(status().isBadRequest());}raw.put("facts_confirmed",false);http.perform(body(post("/api/admin/restrictions"),raw,adminToken)).andExpect(status().isBadRequest());raw.put("facts_confirmed","true");http.perform(body(post("/api/admin/restrictions"),raw,adminToken)).andExpect(status().isBadRequest());assertEquals(403,assertThrows(Api.Failure.class,()->restrictionWorkflow.create(student,create(student))).status);http.perform(auth(get("/api/admin/restrictions").param("status","invalid"),adminToken)).andExpect(status().isBadRequest());}
